/* -------------------------------------------------------------------------- */
/*                                DEPENDENCIES                                */
/* -------------------------------------------------------------------------- */

import { z } from 'zod';

import { SITE_SPEC_FORMAT } from './paths';

/* -------------------------------------------------------------------------- */
/*                                    LOCK                                    */
/* -------------------------------------------------------------------------- */

/*
 * `hlou/site.lock.json`: GENERATED by the export, `readOnly` by path
 * class, never written by hand. It maps every key of the spec to the uuid the
 * row had in the base version, so the import can tell a renamed key from
 * a new row and a removed row from one never exported. A spec without a lock
 * is a fresh site: every row is new, merged against an empty base.
 *
 * Each map is keyed the way the spec names the row:
 *
 * - `pages`, `pageDocuments`: `<pageSlug>`
 * - `sections`: `<pageSlug>/<sectionKey>`
 * - `slots`: `<pageSlug>/<slotKey>`, `site/<slotKey>` (as content keys)
 * - `content`: `<locale>:<pageSlug>/<slotKey>` — one `content_values` row
 * - `components`, `componentDocuments`: `<componentKey>`
 * - `locales`: `<code>`
 * - `collections`, `forms`: `<key>`
 * - `fields`, `records`: `<collectionKey>/<key>`
 * - `media`: `/media/<dir>/<file>` — the asset
 */

const uuid = z.uuid();
const map = z.record(z.string().min(1), uuid);

export const siteSpecLockSchema = z
  .object({
    format: z.literal(SITE_SPEC_FORMAT),
    projectId: uuid,
    /** The version the spec was exported from (`hlou/export.json`'s `siteVersionId`); null for a draft export. */
    baseSiteVersionId: uuid.nullable(),
    /** The project's theme row. */
    theme: uuid.nullable(),
    locales: map,
    pages: map,
    pageDocuments: map,
    sections: map,
    slots: map,
    content: map,
    components: map,
    componentDocuments: map,
    collections: map,
    fields: map,
    forms: map,
    records: map,
    media: map,
  })
  .strict()
  .meta({ readOnly: true });
export type SiteSpecLock = z.infer<typeof siteSpecLockSchema>;

/** The lock's `content` key for one value. */
export function siteSpecLockContentKey(locale: string, contentKey: string): string {
  return `${locale}:${contentKey}`;
}
